import{_ as i,o as d,c as a,a2 as o,j as l}from"./chunks/framework.D66Xq0Kv.js";const b=JSON.parse('{"title":"命令备忘录：Vim","description":"","frontmatter":{"title":"命令备忘录：Vim","date":"2026-09-27","categories":["开发工具","命令备忘录"],"tags":["Vim","命令备忘录"]},"headers":[],"relativePath":"开发工具/命令备忘录：Vim.md","filePath":"开发工具/命令备忘录：Vim.md"}'),c={name:"开发工具/命令备忘录：Vim.md"};function t(r,e,n,u,s,h){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="命令备忘录vim" tabindex="-1">命令备忘录：Vim <a class="header-anchor" href="#命令备忘录vim" aria-label="Permalink to &quot;命令备忘录：Vim&quot;">​</a></h1><h2 id="一操作和移动" tabindex="-1">一、操作和移动 <a class="header-anchor" href="#一操作和移动" aria-label="Permalink to &quot;一、操作和移动&quot;">​</a></h2><p>大部分的vim组合命令 = <a href="#一操作">操作命令（Operator）</a> + <a href="#二字符移动">移动命令（Motion）</a>。</p><ul><li>操作命令表示对光标范围内的文本做什么操作（参见<a href="https://vimhelp.org/motion.txt.html#operator" target="_blank" rel="noreferrer">Operator</a>）。</li><li>移动命令表示光标去哪里或覆盖什么范围（参见<a href="https://vimhelp.org/motion.txt.html" target="_blank" rel="noreferrer">Motion</a>）。</li></ul><p>大多数操作命令和移动命令都可以计数，其格式如下所示：</p><ul><li><code>[Number] [Operator]</code>：重复操作多次。如：<code>2dd</code>，删除当前行，并操作2次（等价于d2j）。</li><li><code>[Number] [Motion]</code>：重复移动多次。如：<code>3j</code>，向下移动3行。</li><li><code>[Number] [Operator] [Number] [Motion]</code>：重复操作和移动的组合多次。如：<code>2d3j</code>，向下删除3行，并操作2次（等价于d6j，合计删除6行）。</li></ul><h3 id="一操作" tabindex="-1">（一）操作 <a class="header-anchor" href="#一操作" aria-label="Permalink to &quot;（一）操作&quot;">​</a></h3><ul><li><code>d</code> 删除</li><li><code>y</code> 复制</li><li><code>c</code> 更改（删除，并进入插入模式）</li><li><code>gu</code> 转小写</li><li><code>gU</code> 转大写</li></ul><h3 id="二字符移动" tabindex="-1">（二）字符移动 <a class="header-anchor" href="#二字符移动" aria-label="Permalink to &quot;（二）字符移动&quot;">​</a></h3><ul><li><code>h</code> 向左移动光标</li><li><code>j</code> 向下移动光标</li><li><code>k</code> 向上移动光标</li><li><code>l</code> 向右移动光标</li></ul><h3 id="三单词移动" tabindex="-1">（三）单词移动 <a class="header-anchor" href="#三单词移动" aria-label="Permalink to &quot;（三）单词移动&quot;">​</a></h3><ul><li><code>w</code> 移动光标到下一个单词的开头</li><li><code>W</code> 移动到下一个词组的开头</li><li><code>e</code> 移动光标到当前单词的结尾</li><li><code>E</code> 移动到下一个词组的结尾</li><li><code>b</code> 移动光标到上一个单词的开头</li><li><code>B</code> 移动到前一个词组的开头</li><li><code>ge</code> 移动光标到上一个单词的结尾</li><li><code>gE</code> 移动到前一个词组的结尾</li></ul><h3 id="四行内移动" tabindex="-1">（四）行内移动 <a class="header-anchor" href="#四行内移动" aria-label="Permalink to &quot;（四）行内移动&quot;">​</a></h3><ol><li>行内普通移动</li></ol><ul><li><code>0</code> 跳到本行第一个字符</li><li><code>^</code> 跳到本行第一个非空字符</li><li><code>$</code> 跳到本行最后一个字符</li><li><code>g_</code> 跳到本行最后一个非空字符</li><li><code>[Number]|</code> 跳到本行指定列</li></ul><ol start="2"><li>行内搜索移动</li></ol><ul><li><code>f</code> 在同一行向后搜索第一个匹配</li><li><code>F</code> 在同一行向前搜索第一个匹配</li><li><code>t</code> 在同一行向后搜索第一个匹配，并停在匹配前</li><li><code>T</code> 在同一行向前搜索第一个匹配，并停在匹配前</li><li><code>;</code> 在同一行重复最近一次搜索</li><li><code>,</code> 在同一行向相反方向重复最近一次搜索</li></ul><h3 id="五结构移动" tabindex="-1">（五）结构移动 <a class="header-anchor" href="#五结构移动" aria-label="Permalink to &quot;（五）结构移动&quot;">​</a></h3><ol><li>匹配移动</li></ol><ul><li><code>%</code> 查找配对的括号 <code>)</code>、<code>]</code>、<code>}</code></li></ul><ol start="2"><li>句子和段落移动（文本对象，参见<a href="https://vimhelp.org/motion.txt.html#object-motions" target="_blank" rel="noreferrer">Text object motions</a>）</li></ol><ul><li><code>(</code> 跳到前一个句子</li><li><code>)</code> 跳到下一个句子</li><li><code>{</code> 跳转到上一个段落</li><li><code>}</code> 跳转到下一个段落</li></ul><ol start="3"><li>文本对象选区（参见<a href="https://vimhelp.org/motion.txt.html#object-select" target="_blank" rel="noreferrer">Text object selection</a>）</li></ol><blockquote><p>适用于在可视化模式下或在操作符之后使用，无法单独进行光标移动</p></blockquote><ul><li>i[对象] 内部文本对象（选中的部分不包含包围文本对象的空白或括号）</li><li>a[对象] 外部文本对象（选中的部分包含包围文本对象的空白或括号）</li></ul>',25),l("table",{tabindex:"0"},[l("thead",null,[l("tr",null,[l("th",null,"对象"),l("th",null,"描述")])]),l("tbody",null,[l("tr",null,[l("td",null,"w"),l("td",null,"一个单词")]),l("tr",null,[l("td",null,"W"),l("td",null,"一个词组")]),l("tr",null,[l("td",null,"s"),l("td",null,"一个句子")]),l("tr",null,[l("td",null,"p"),l("td",null,"一个段落")]),l("tr",null,[l("td",null,"(或)"),l("td",null,"一对()")]),l("tr",null,[l("td",{或:""}),l("td",null,"一对{}")]),l("tr",null,[l("td",null,"[或]"),l("td",null,"一对[]")]),l("tr",null,[l("td",null,"<或>"),l("td",null,"一对<>")]),l("tr",null,[l("td",null,"t"),l("td",null,"XML标签")]),l("tr",null,[l("td",null,'"'),l("td",null,'一对""')]),l("tr",null,[l("td",null,"'"),l("td",null,"一对''")]),l("tr",null,[l("td",null,"`"),l("td",null,"一对``")])])],-1),o(`<h3 id="六全文移动" tabindex="-1">（六）全文移动 <a class="header-anchor" href="#六全文移动" aria-label="Permalink to &quot;（六）全文移动&quot;">​</a></h3><ol><li>行号移动</li></ol><ul><li><code>gg</code> 跳转到第一行</li><li><code>G</code> 跳转到最后一行</li><li><code>[Number] G</code> 跳转到指定行，如 <code>6G</code> 移动到第6行</li><li><code>ctrl-g</code> 显示当前光标所在行位置以及文件状态信息</li><li><code>:set relativenumber number</code> 展示当前行号和其他行相对当前行的行号</li></ul><ol start="2"><li>全文搜索移动</li></ol><ul><li><code>/</code> 向后搜索一个匹配</li><li><code>?</code> 向前搜素一个匹配</li><li><code>n</code> 重复上一次搜索(和上一次方向相同)</li><li><code>N</code> 重复上一次搜索(和上一次方向相反)</li><li><code>*</code> 向后查找光标所在的完整单词</li><li><code>#</code> 向前查找光标所在的完整单词</li><li><code>g*</code> 向后搜索光标所在的单词</li><li><code>g#</code> 向前搜索光标所在的单词</li><li><code>:set hlsearch</code> 设置搜索高亮</li><li><code>:set incsearch</code> 设置增量搜索，输入时不断匹配输入内容</li></ul><h3 id="七屏幕移动" tabindex="-1">（七）屏幕移动 <a class="header-anchor" href="#七屏幕移动" aria-label="Permalink to &quot;（七）屏幕移动&quot;">​</a></h3><ol><li>视图滚动浏览</li></ol><blockquote><p>调整【文本视图】到特定位置</p></blockquote><ul><li><code>ctrl-e</code> 向下滚一行</li><li><code>ctrl-d</code> 向下翻半页（d = down）</li><li><code>ctrl-f</code> 向下一翻页（f = forword ）</li><li><code>ctrl-y</code> 向上滚一行</li><li><code>ctlr-u</code> 向上翻半页（u = up）</li><li><code>ctrl-b</code> 向上一翻页（b = backward）</li></ul><ol start="2"><li>视图重排对齐</li></ol><blockquote><p>调整【文本视图】以对齐【屏幕】特定位置（以当前光标所在行为基准）</p></blockquote><ul><li><code>zz</code> 让光标所在的行居屏幕中央</li><li><code>zt</code> 让光标所在的行居屏幕最上一行（t = top）</li><li><code>zb</code> 让光标所在的行居屏幕最下一行（b = bottom）</li></ul><ol start="3"><li>屏幕光标定位</li></ol><blockquote><p>【文本视图】不动，将光标移动到当前可见【屏幕】的特定相对位置</p></blockquote><ul><li><code>H</code> 跳转到屏幕的顶部</li><li><code>M</code> 跳转到屏幕的中间</li><li><code>L</code> 跳转到屏幕的底部</li><li><code>nH</code> 跳转到距离顶部n行的位置</li><li><code>nL</code> 跳转到距离底部n行的位置</li></ul><blockquote><p>LasyVim的bufferline插件映射了H和L（缓冲区切换）</p></blockquote><h3 id="八标记与跳转" tabindex="-1">（八）标记与跳转 <a class="header-anchor" href="#八标记与跳转" aria-label="Permalink to &quot;（八）标记与跳转&quot;">​</a></h3><ol><li>标记（参见<a href="https://vimhelp.org/motion.txt.html#mark-motions" target="_blank" rel="noreferrer">Marks</a>）</li></ol><ul><li><code>m[Mark]</code> 用标签标记一个位置</li><li><code>&#39;[Mark]</code> 跳转到指定标签的行</li><li><code> \`[Mark]</code> 精确回到指定标签的位置(行和列)</li><li><code>:marks</code> 查看所有标记</li></ul><ol start="2"><li>跳转（参见<a href="https://vimhelp.org/motion.txt.html#jump-motions" target="_blank" rel="noreferrer">Jumps</a>）</li></ol><ul><li><code>:jumps</code> 查看跳转列表</li><li><code>ctrl-i</code> 跳转到之后的位置</li><li><code>ctrl-o</code> 跳转到之前的位置</li></ul><h2 id="二其它" tabindex="-1">二、其它 <a class="header-anchor" href="#二其它" aria-label="Permalink to &quot;二、其它&quot;">​</a></h2><h3 id="一进入插入模式" tabindex="-1">（一）进入插入模式 <a class="header-anchor" href="#一进入插入模式" aria-label="Permalink to &quot;（一）进入插入模式&quot;">​</a></h3><ul><li><code>i</code> 在光标处，进入插入模式</li><li><code>a</code> 在光标所在单词之后，进入插入模式</li><li><code>A</code> 在光标所在行的行末，进入插入模式</li><li><code>o</code> 在光标下方另起一行，进入插入模式</li><li><code>O</code> 在光标上方另起一行，进入插入模式</li></ul><h3 id="二常用编辑指令" tabindex="-1">（二）常用编辑指令 <a class="header-anchor" href="#二常用编辑指令" aria-label="Permalink to &quot;（二）常用编辑指令&quot;">​</a></h3><ul><li><code>p</code> 粘贴</li><li><code>u</code> 撤销</li><li><code>ctrl-r</code> 恢复撤销</li><li><code>x</code> 删除光标后的一个字符</li><li><code>s</code> 删除光标后的一个字符，进入插入模式</li><li><code>r</code> 替换光标后的一个字符</li><li><code>R</code> 连续替换光标后的多个字符</li></ul><blockquote><p>LasyVim下的flash插件映射了s（搜索），可以使用cl替换</p></blockquote><h3 id="三替换" tabindex="-1">（三）替换 <a class="header-anchor" href="#三替换" aria-label="Permalink to &quot;（三）替换&quot;">​</a></h3><ul><li><code>:%s/old/new</code> 将第一个查找到的old替换为new</li><li><code>:%s/old/new/g</code> 将所有的old替换为new</li><li><code>:%s/old/new/gc</code> 将所有的old替换为new，替换时需要确认</li><li><code>[Number],[Number]s/old/new/g</code> 将指定两行的old替换为new</li></ul><h3 id="四常用工具" tabindex="-1">（四）常用工具 <a class="header-anchor" href="#四常用工具" aria-label="Permalink to &quot;（四）常用工具&quot;">​</a></h3><ul><li><code>:! [COMMAND]</code> 执行外部命令</li><li><code>:w [FILENAME]</code> 另存为文件</li><li><code>v :w [FILENAME]</code> 在可视模式下，将选中内容另存为文件</li><li><code>:r [FILENAME]</code> 粘贴文件内容</li><li><code>:r ![COMMOND]</code> 粘贴外部命令输出</li></ul><h3 id="五可视化块" tabindex="-1">（五）可视化块 <a class="header-anchor" href="#五可视化块" aria-label="Permalink to &quot;（五）可视化块&quot;">​</a></h3><p>使用可视化块实现列编辑：</p><p>（1）批量删除多行的指定列的字符（如#注释字符）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ctrl+v        &quot; 进入块选择</span></span>
<span class="line"><span>6j            &quot; 向下选 6 行</span></span>
<span class="line"><span>d             &quot; 删掉这一竖列</span></span></code></pre></div><p>（2）批量插入多行的指定列的字符</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ctrl+v        &quot; 进入块选择</span></span>
<span class="line"><span>6j            &quot; 向下选 6 行</span></span>
<span class="line"><span>I             &quot; 在块的左边界批量插入，右边界使用A</span></span>
<span class="line"><span>#             &quot; 输入任意想要插入的字符（如#注释字符）</span></span>
<span class="line"><span>Esc           &quot; 退出可视块模式，并使批量插入动作生效</span></span></code></pre></div><blockquote><p>参考文档</p></blockquote><ol><li><a href="https://github.com/iggredible/Learn-Vim" target="_blank" rel="noreferrer">Learn-Vim</a></li><li><code>vimtutor</code></li><li><a href="https://vimhelp.org/" target="_blank" rel="noreferrer">vimhelp</a></li></ol>`,39)])])}const m=i(c,[["render",t]]);export{b as __pageData,m as default};
